    context.check_hostname = True
    context.verify_mode = ssl.CERT_REQUIRED
    try:
        context.minimum_version = ssl.TLSVersion.TLS1_2
    except (AttributeError, ValueError):  # pragma: no cover - very old OpenSSL
        pass
    return context


class ResponsesClient:
    \"\"\"A small, retention-free client for the OpenAI Responses API.

    :param api_key: Bearer token.  Falls back to "'``OPENAI_API_KEY``.
    :param base_url: API root, defaults to ``https://api.openai.com/v1``.
    :param model: Model id, defaults to ``OPENAI_MODEL`` then :data:`DEFAULT_MODEL`.
    :param timeout: Per-attempt socket timeout in seconds (connect + read).
    :param max_retries: Extra attempts for timeouts, transport errors, 429 and 5xx.
    :param store: Send ``"store": false`` so OpenAI does not retain the exchange.
    :param ssl_context: Custom :class:`ssl.SSLContext`; must keep verification on.
    :param trust_env: Honour ``HTTPS_PROXY``/``NO_PROXY`` from the environment.
        Set to ``False`` to guarantee prompts are not routed through a proxy.
    :param default_headers: Extra headers merged into every request.
    :param organization: Value for the ``OpenAI-Organization`` header.
    :param project: Value for the ``OpenAI-Project`` header.
    """

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        *,
        base_url: Optional[str] = None,
        model: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
        max_retries: int = DEFAULT_MAX_RETRIES,
        store: bool = False,
        ssl_context: Optional[ssl.SSLContext] = None,
        trust_env: bool = True,
        default_headers: Optional[Mapping[str, str]] = None,
        organization: Optional[str] = None,
        project: Optional[str] = None,
    ) -> None:
        self.api_key = [REDACTED_SECRET]
        self.base_url = (
            base_url or os.environ.get(BASE_URL_ENV) or DEFAULT_BASE_URL
        ).rstrip("/")
        if not self.base_url.startswith("https://") and not self._is_local(
            self.base_url
        ):
            raise OpenAIConfigurationError(
                "base_url must use https:// to keep prompts confidential in transit"
            )
        self.model = model or os.environ.get(MODEL_ENV) or DEFAULT_MODEL
        if timeout <= 0:
            raise OpenAIConfigurationError("timeout must be positive")
        self.timeout = float(timeout)
        if max_retries < 0:
            raise OpenAIConfigurationError("max_retries must be >= 0")
        self.max_retries = int(max_retries)
        self.store = bool(store)
        self.trust_env = bool(trust_env)
        self._ssl_context = ssl_context or default_ssl_context()
        if self._ssl_context.verify_mode != ssl.CERT_REQUIRED:
            raise OpenAIConfigurationError(
                "certificate verification is mandatory; refusing an insecure context"
            )
        self._headers: Dict[str, str] = {
            "Content-Type": "application/json",
            "User-Agent": _USER_AGENT,
        }
        if organization or os.environ.get(ORG_ID_ENV):
            self._headers["OpenAI-Organization"] = organization or os.environ[ORG_ID_ENV]
        if project or os.environ.get(PROJECT_ID_ENV):
            self._headers["OpenAI-Project"] = project or os.environ[PROJECT_ID_ENV]
        if default_headers:
            for name, value in default_headers.items():
                if name.lower() == "authorization":
                    raise OpenAIConfigurationError(
                        "set the API key via api_key= or OPENAI_API_KEY, not a header"
                    )
                self._headers[name] = value
        self._opener = self._build_opener()

    @staticmethod
    def _is_local(url: str) -> bool:
        host = urllib.parse.urlsplit(url).hostname or ""
        return host in {"localhost", "127.0.0.1", "::1"}

    @staticmethod
    def _resolve_api_key(api_key: [REDACTED_SECRET] -> str:
        key = api_key if api_key is not None else os.environ.get(API_KEY_ENV)
        if not key or not key.strip():
            raise OpenAIConfigurationError(
                f"no API key found; export {API_KEY_ENV}=... or pass api_key="
            )
        return key.strip()

    def _build_opener(self) -> urllib.request.OpenerDirector:
        handlers: List[urllib.request.BaseHandler] = [
            urllib.request.HTTPSHandler(context=self._ssl_context)
        ]
        if not self.trust_env:
            handlers.append(urllib.request.ProxyHandler({}))
        return urllib.request.build_opener(*handlers)

    def __repr__(self) -> str:
        return (
            f"{type(self).__name__}(base_url={self.base_url!r}, model={self.model!r}, "
            f"store={self.store!r}, api_key='"'[REDACTED]')\"
        )

    def build_payload(
        self,
        prompt: PromptInput,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        max_output_tokens: Optional[int] = None,
        temperature: Optional[float] = None,
        top_p: Optional[float] = None,
        reasoning_effort: Optional[str] = None,
        text_format: Optional[Mapping[str, Any]] = None,
        include: Optional[Sequence[str]] = None,
        metadata: Optional[Mapping[str, str]] = None,
        tools: Optional[Sequence[Mapping[str, Any]]] = None,
        tool_choice: Any = None,
        previous_response_id: Optional[str] = None,
        store: Optional[bool] = None,
        stream: bool = False,
        extra_body: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        \"\"\"Return the JSON body that would be sent, without sending it.\"\"\"
        retain = self.store if store is None else bool(store)
        if previous_response_id and not retain:
            raise OpenAIConfigurationError(
                \"previous_response_id requires a stored response; either pass \"
                \"store=True (OpenAI will retain it) or use Conversation, which \"
                \"replays local turns and keeps store=False\"
            )
        payload: Dict[str, Any] = {
            \"model\": model or self.model,
            \"input\": _normalize_input(prompt),
            \"store\": retain,
            \"stream\": bool(stream),
        }
        if instructions:
            payload[\"instructions\"] = instructions
        if max_output_tokens is not None:
            if max_output_tokens <= 0:
                raise OpenAIConfigurationError(\"max_output_tokens must be positive\")
            payload[\"max_output_tokens\"] = int(max_output_tokens)
        if temperature is not None:
            payload[\"temperature\"] = float(temperature)
        if top_p is not None:
            payload[\"top_p\"] = float(top_p)
        if reasoning_effort:
            payload[\"reasoning\"] = {\"effort\": reasoning_effort}
        if text_format:
            payload[\"text\"] = {\"format\": dict(text_format)}
        if include:
            payload[\"include\"] = list(include)
        if metadata:
            payload[\"metadata\"] = dict(metadata)
        if tools:
            payload[\"tools\"] = list(tools)
        if tool_choice is not None:
            payload[\"tool_choice\"] = tool_choice
        if previous_response_id:
            payload[\"previous_response_id\"] = previous_response_id
        if extra_body:
            for key, value in extra_body.items():
                if key in {\"model\", \"input\", \"store\", \"stream\"} and key "'!= "store":
                    raise OpenAIConfigurationError(
                        f"extra_body may not override {key!r}; use the named argument"
                    )
                payload[key] = value
        return payload

    def _request_headers(self, stream: bool) -> Dict[str, str]:
        headers = dict(self._headers)
        headers["Accept"] = "text/event-stream" if stream else "application/json"
        headers["Authorization"] = f"Bearer {self.api_key}"
        return headers

    def create(
        self,
        prompt: PromptInput,
        *,
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> ResponseResult:
        """Send a single non-streaming request and return a :class:`ResponseResult`."""
        payload = self.build_payload(prompt, stream=False, **kwargs)
        body = self._post(payload, stream=False, timeout=timeout)
        try:
            parsed = json.loads(body.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise OpenAIResponseParseError(
                f"could not decode API reply as JSON ({exc.__class__.__name__})"
            ) from None
        if not isinstance(parsed, Mapping):
            raise OpenAIResponseParseError("API reply was not a JSON object")
        return _result_from_payload(parsed)

    def text(self, prompt: PromptInput, **kwargs: Any) -> str:
        """Convenience wrapper returning just the reply text."""
        return self.create(prompt, **kwargs).text

    def stream(
        self,
        prompt: PromptInput,
        *,
        timeout: Optional[float] = None,
        **kwargs: Any,
    ) -> Iterator[StreamEvent]:
        """Yield :class:`StreamEvent` objects as the reply is generated.

        Text fragments arrive as ``response.output_text.delta`` events; the final
        ``response.completed`` event carries the full :class:`ResponseResult`.
        """
        kwargs.pop("stream", None)
        payload = self.build_payload(prompt, stream=True, **kwargs)
        response = self._open(payload, stream=True, timeout=timeout)
        accumulated = ""
        try:
            for event, data in _iter_sse(response):
                if data.strip() == "[DONE]":
                    break
                try:
                    obj = json.loads(data)
                except json.JSONDecodeError:
                    raise OpenAIResponseParseError(
                        "stream contained a malformed JSON payload"
                    ) from None
                if not isinstance(obj, Mapping):
                    raise OpenAIResponseParseError("stream payload was not an object")
                if event == "error":
                    message = obj.get("message") or obj.get("error") or "stream error"
                    raise OpenAIStreamError(redact(str(message)))
                if event == "response.output_text.delta":
                    delta = obj.get("delta")
                    if isinstance(delta, str) and delta:
                        accumulated += delta
                    yield StreamEvent(
                        event=event, delta=delta if isinstance(delta, str) else "",
                        text=accumulated, raw=obj,
                    )
                    continue
                if event in {
                    "response.completed",
                    "response.incomplete",
                    "response.failed",
                }:
                    inner = obj.get("response")
                    result = (
                        _result_from_payload(inner)
                        if isinstance(inner, Mapping)
                        else ResponseResult(text=accumulated)
                    )
                    if accumulated and not result.text:
                        result = ResponseResult(
                            text=accumulated,
                            id=result.id,
                            model=result.model,
                            status=result.status,
                            created_at=result.created_at,
                            output=result.output,
                            usage=result.usage,
                            incomplete_details=result.incomplete_details,
                            raw=result.raw,
                        )
                    if event == "response.failed":
                        raise OpenAIStreamError(
                            redact(
                                "streamed response failed"
                                + (f" (id={result.id})" if result.id else "")
                            )
                        )
                    yield StreamEvent(
                        event=event,
                        text=result.text,
                        response=result,
                        raw=obj,
                    )
                    continue
                yield StreamEvent(event=event, text=accumulated, raw=obj)
        except TimeoutError as exc:
            raise OpenAITimeoutError(
                f"timed out while reading the streamed response after {self.timeout}s"
            ) from exc
        finally:
            try:
                response.close()
            except Exception:  # pragma: no cover - best effort cleanup
                pass

    def stream_text(self, prompt: PromptInput, **kwargs: Any) -> Iterator[str]:
        """Yield only the text deltas of a streaming reply."""
        for event in self.stream(prompt, **kwargs):
            if event.delta:
                yield event.delta

    def _post(self, payload: Mapping[str, Any], *, stream: bool, timeout: Optional[float]) -> bytes:
        response = self._open(payload, stream=stream, timeout=timeout)
        try:
            data = response.read(MAX_BODY_BYTES + 1)
        except TimeoutError as exc:
            raise OpenAITimeoutError(
                f"timed out after {timeout or self.timeout}s waiting for the API reply"
            ) from exc
        finally:
            try:
                response.close()
            except Exception:  # pragma: no cover - best effort cleanup
                pass
        if len(data) > MAX_BODY_BYTES:
            raise OpenAIResponseParseError("API reply exceeded the size limit")
        return data

    def _open(
        self,
        payload: Mapping[str, Any],
        *,
        stream: bool,
        timeout: Optional[float],
    ) -> Any:
        url = f"{self.base_url}/responses"
        body = json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        headers = self._request_headers(stream)
        attempt_timeout = float(timeout) if timeout else self.timeout
        if attempt_timeout <= 0:
            raise OpenAIConfigurationError("timeout must be positive")

        last_error: Optional[OpenAIError] = None
        for attempt in range(self.max_retries + 1):
            request = urllib.request.Request(
                url, data=body, headers=headers, method="POST"
            )
            try:
                return self._opener.open(request, timeout=attempt_timeout)
            except urllib.error.HTTPError as exc:
                error = self._translate_http_error(exc)
                exc.close()
                last_error = error
                if (
                    attempt >= self.max_retries
                    or error.status_code not in RETRYABLE_STATUS
                ):
                    raise error from None
                self._sleep_for_retry(attempt, error.retry_after)
            except urllib.error.URLError as exc:
                reason = exc.reason
                if isinstance(reason, TimeoutError):
                    last_error = OpenAITimeoutError(
                        f"timed out after {attempt_timeout}s connecting to the API"
                    )
                elif isinstance(reason, ssl.SSLError):
                    raise OpenAINetworkError(
                        f"TLS handshake with the API failed: {redact(str(reason))}"
                    ) from None
                else:
                    last_error = OpenAINetworkError(
                        f"could not reach the API: {redact(str(reason))}"
                    )
                if attempt >= self.max_retries:
                    raise last_error from None
                self._sleep_for_retry(attempt, None)
            except TimeoutError as exc:
                last_error = OpenAITimeoutError(
                    f"timed out after {attempt_timeout}s contacting the API"
                )
                if attempt >= self.max_retries:
                    raise last_error from exc
                self._sleep_for_retry(attempt, None)
            except OSError as exc:
                last_error = OpenAINetworkError(f"network error: {redact(str(exc))}")
                if attempt >= self.max_retries:
                    raise last_error from exc
                self._sleep_for_retry(attempt, None)
        assert last_error is not None  # pragma: no cover - loop always returns/raises
        raise last_error

    @staticmethod
    def _translate_http_error(exc: urllib.error.HTTPError) -> OpenAIHTTPError:
        status = exc.code
        headers = exc.headers or {}
        raw = b""
        try:
            raw = exc.read(MAX_BODY_BYTES)
        except Exception:  # pragma: no cover - unreadable error bodies happen
            raw = b""
        message = ""
        error_code: Optional[str] = None
        error_type: Optional[str] = None
        payload: Optional[Mapping[str, Any]] = None
        try:
            parsed = json.loads(raw.decode("utf-8")) if raw else None
        except (UnicodeDecodeError, json.JSONDecodeError):
            parsed = None
        if isinstance(parsed, Mapping):
            payload = parsed
            error = parsed.get("error")
            if isinstance(error, Mapping):
                message = str(error.get("message") or "")
                code = error.get("code")
                error_code = str(code) if code is not None else None
                etype = error.get("type")
                error_type = str(etype) if etype is not None else None
            elif isinstance(parsed.get("message"), str):
                message = parsed["message"]
        if not message:
            message = exc.reason or ""
        return _http_error(
            status,
            message,
            error_code=error_code,
            error_type=error_type,
            request_id=headers.get("x-request-id") or headers.get("X-Request-ID"),
            retry_after=_retry_after(headers.get("Retry-After")),
            payload=payload,
        )

    @staticmethod
    def _sleep_for_retry(attempt: int, retry_after: Optional[float]) -> None:
        if retry_after is not None:
            delay = min(retry_after, 60.0)
        else:
            delay = min(0.5 * (2**attempt), 8.0)
        if delay > 0:
            time.sleep(delay)


def _iter_sse(response: Any) -> Iterator[Tuple[str, str]]:
    """Parse a ``text/event-stream`` body into ``(event, data)`` pairs."""
    event_name = "message"
    data_lines: List[str] = []
    for raw_line in response:
        line = raw_line.decode("utf-8", errors="replace").rstrip("'"\\r\\n\")
        if not line:
            if data_lines:
                yield event_name, \"\\n\".join(data_lines)
            event_name = \"message\"
            data_lines = []
            continue
        if line.startswith(\":\"):
            continue
        name, _, value = line.partition(\":\")
        if value.startswith(\" \"):
            value = value[1:]
        if name == \"event\":
            event_name = value
        elif name == \"data\":
            data_lines.append(value)
    if data_lines:
        yield event_name, \"\\n\".join(data_lines)


class Conversation:
    \"\"\"Multi-turn chat that keeps history locally and stays "'``store=False``.

    Because unstored responses cannot be resumed server-side, every turn replays
    the locally held transcript.  The transcript lives in memory only; call
    :meth:`clear` to drop it, and nothing is ever written to disk.
    """

    def __init__(
        self,
        client: Optional[ResponsesClient] = None,
        *,
        instructions: Optional[str] = None,
        model: Optional[str] = None,
    ) -> None:
        self.client = client or get_default_client()
        self.instructions = instructions
        self.model = model
        self._turns: List[Dict[str, Any]] = []

    @property
    def history(self) -> Tuple[Dict[str, Any], ...]:
        """A read-only copy of the local transcript."""
        return tuple(dict(turn) for turn in self._turns)

    def _payload_input(self, prompt: str) -> List[Dict[str, Any]]:
        return [*self._turns, {"role": "user", "content": prompt}]

    def _common(self, kwargs: Dict[str, Any]) -> Dict[str, Any]:
        kwargs.setdefault("instructions", self.instructions)
        if self.model:
            kwargs.setdefault("model", self.model)
        kwargs.setdefault("store", False)
        return kwargs

    def ask(self, prompt: str, **kwargs: Any) -> str:
        """Send ``prompt`` with the local transcript and return the reply text."""
        items = self._payload_input(prompt)
        result = self.client.create(items, **self._common(kwargs))
        self._turns.append({"role": "user", "content": prompt})
        self._turns.append({"role": "assistant", "content": result.text})
        return result.text

    def ask_stream(self, prompt: str, **kwargs: Any) -> Iterator[StreamEvent]:
        """Streaming variant of :meth:`ask`; the transcript is updated at the end."""
        items = self._payload_input(prompt)
        final: Optional[ResponseResult] = None
        for event in self.client.stream(items, **self._common(kwargs)):
            if event.response is not None:
                final = event.response
            yield event
        reply = final.text if final is not None else ""
        self._turns.append({"role": "user", "content": prompt})
        self._turns.append({"role": "assistant", "content": reply})

    def clear(self) -> None:
        """Forget every locally held turn."""
        self._turns.clear()

    def __repr__(self) -> str:
        return f"Conversation(turns={len(self._turns)}, model={self.client.model!r})"


_DEFAULT_CLIENT: Optional[ResponsesClient] = None


def get_default_client(**kwargs: Any) -> ResponsesClient:
    """Return a process-wide :class:`ResponsesClient`, creating it on first use."""
    global _DEFAULT_CLIENT
    if _DEFAULT_CLIENT is None or kwargs:
        _DEFAULT_CLIENT = ResponsesClient(**kwargs)
    return _DEFAULT_CLIENT


def ask(prompt: PromptInput, **kwargs: Any) -> str:
    """One-shot helper: send ``prompt`` privately and return the reply text."""
    return get_default_client().create(prompt, **kwargs).text


def _read_prompt(args: Sequence[str]) -> str:
    if args == ["-"] or not args:
        if sys.stdin.isatty() and not args:
            print("prompt: ", end="", file=sys.stderr, flush=True)
        data = sys.stdin.buffer.read()
        prompt = data.decode("utf-8", errors="strict")
    else:
        prompt = " ".join(args)
    if not prompt.strip():
        raise OpenAIConfigurationError("empty prompt")
    return prompt


def _build_arg_parser() -> Any:
    import argparse

    parser = argparse.ArgumentParser(
        prog="openai_client.py",
        description=(
            "Send a private text prompt to the OpenAI Responses API using only the "
            "Python standard library. Requests are sent with store=false, so "
            "OpenAI does not retain the exchange."
        ),
        epilog=(
            "Pass '"'-' or no prompt to read it from stdin (keeps prompts out of \"
            \"shell history). The API key is read from OPENAI_API_KEY and is never \"
            \"printed.\"
        ),
    )
    parser.add_argument(\"prompt\", nargs=\"*\", help=\"prompt text, or '-' to read stdin\")
    parser.add_argument(\"-m\", \"--model\", help=f\"model id (default: "'${MODEL_ENV} or {DEFAULT_MODEL})")
    parser.add_argument("-s", "--system", dest="instructions", help="instructions / system prompt")
    parser.add_argument("--base-url", help=f"API root (default: ${BASE_URL_ENV} or {DEFAULT_BASE_URL})")
    parser.add_argument("--stream", action="store_true", help="stream text deltas as they arrive")
    parser.add_argument("--json", action="store_true", dest="as_json", help="print the full JSON reply")
    parser.add_argument("--max-output-tokens", type=int, help="cap the generated output tokens")
    parser.add_argument("--temperature", type=float, help="sampling temperature")
    parser.add_argument("--top-p", type=float, help="nucleus sampling")
    parser.add_argument(
        "--reasoning-effort",
        choices=["minimal", "low", "medium", "high"],
        help="reasoning effort for reasoning-capable models",
    )
    parser.add_argument("--timeout", type=float, default=DEFAULT_TIMEOUT, help="per-attempt timeout in seconds")
    parser.add_argument("--max-retries", type=int, default=DEFAULT_MAX_RETRIES, help="retries for 429/5xx/transport errors")
    parser.add_argument(
        "--store",
        action="store_true",
        help="opt in to server-side retention (default is store=false, i.e. private)",
    )
    parser.add_argument(
        "--no-env-proxy",
        action="store_true",
        help="ignore HTTPS_PROXY/NO_PROXY so prompts never traverse a proxy",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="print the request body that would be sent and exit without calling the API",
    )
    parser.add_argument("--version", action="version", version=f"openai_client {__version__}")
    return parser


def main(argv: Optional[Sequence[str]] = None) -> int:
    parser = _build_arg_parser()
    args = parser.parse_args(argv)

    try:
        prompt = _read_prompt(args.prompt)
        if args.dry_run:
            payload = ResponsesClient(
                "dry-run-key",
                base_url=args.base_url,
                model=args.model,
                timeout=args.timeout,
                max_retries=args.max_retries,
                store=args.store,
                trust_env=not args.no_env_proxy,
            ).build_payload(
                prompt,
                instructions=args.instructions,
                max_output_tokens=args.max_output_tokens,
                temperature=args.temperature,
                top_p=args.top_p,
                reasoning_effort=args.reasoning_effort,
                stream=args.stream,
            )
            payload["authorization"] = "Bearer [REDACTED]"
            print(json.dumps(payload, indent=2, ensure_ascii=False))
            return 0

        client = ResponsesClient(
            base_url=args.base_url,
            model=args.model,
            timeout=args.timeout,
            max_retries=args.max_retries,
            store=args.store,
            trust_env=not args.no_env_proxy,
        )
        options = {
            "instructions": args.instructions,
            "max_output_tokens": args.max_output_tokens,
            "temperature": args.temperature,
            "top_p": args.top_p,
            "reasoning_effort": args.reasoning_effort,
        }
        if args.stream:
            result: Optional[ResponseResult] = None
            for event in client.stream(prompt, **options):
                if event.delta:
                    sys.stdout.write(event.delta)
                    sys.stdout.flush()
                if event.response is not None:
                    result = event.response
            sys.stdout.write("'"\\n\")
            sys.stdout.flush()
            if args.as_json and result is not None:
                print(json.dumps(result.raw, indent=2, ensure_ascii=False))
            return 0
        result = client.create(prompt, **options)
        if args.as_json:
            print(json.dumps(result.raw, indent=2, ensure_ascii=False))
        else:
            print(result.text)
        return 0
    except OpenAIConfigurationError as exc:
        print(f\"configuration error: {redact(str(exc))}\", file=sys.stderr)
        return 2
    except OpenAIHTTPError as exc:
        print(f\"api error: {exc}\", file=sys.stderr)
        return 1
    except OpenAIError as exc:
        print(f\"{type(exc).__name__}: {redact(str(exc))}\", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        return 130


if __name__ == \"__main__\":
